import skarstrom as sk

sim = sk.Simulation.new()
sim.info.title = 'Streb 2021 - Experiment A1'
sim.info.description = 'Binary CO2/CH4 separation breakthrough test based on Streb et al. 2021, experiment A1. This simulation models a breakthrough experiment for 13X zeolite in a lab-scale test rig at atmospheric pressure (1 bar). This is identical to experiment A3 except operated at lower pressure, allowing comparison of pressure effects on separation performance. The bed is initially saturated with helium and then fed with an equimolar binary mixture of CO2 and CH4. The adsorbent uses an Extended Sips2 isotherm model for both components and linear driving force models for mass transfer. The simulation includes coupled heat and mass transfer with internal and external heat transfer mechanisms. Wall heat transfer is neglected in this configuration. Experimental breakthrough data is included and can be plotted to validate the solver performance. This test demonstrates the ability to model competitive adsorption in binary systems at atmospheric pressure conditions.'
sim.info.author = 'Sam Affleck'

# ---- fluid --------------------------------------------------------------------
sim.add_component('CarbonDioxide')
sim.add_component('Methane')
sim.add_component('Helium')
sim.fluid.adsorbed_heat_capacity_mode = 0
sim.fluid.heat_of_adsorption_convention = 0
sim.fluid.adsorbed_heat_capacity['CarbonDioxide'] = 0.0
sim.fluid.adsorbed_heat_capacity['Methane'] = 0.0
sim.fluid.adsorbed_heat_capacity['Helium'] = 0.0

# ---- adsorbents -----------------------------------------------------------------
ads_13x = sim.add_adsorbent('13X', solid_density=1085.0, heat_capacity=1100.0, thermal_conductivity=0.15, particle_void_fraction=0.5400593471810089)
ads_13x.set_isotherm('extended_sips_2', {
    'CarbonDioxide': {'A1': 7.268, 'A2': -0.6168, 'B1': 1.129e-09, 'B2': 28389.0, 'C1': 0.425, 'C2': 0.7238, 'T_ref': 298.0},
    'Methane': {'A1': 4.473, 'A2': -0.6569, 'B1': 3.605e-09, 'B2': 15561.0, 'C1': 1.073, 'C2': 0.0, 'T_ref': 298.0},
}, components=['CarbonDioxide', 'Methane'])
ads_13x.set_isotherm('inert', components=['Helium'])
ads_13x.set_rate_model('CarbonDioxide', 'ldf', 'constant', k=0.06)
ads_13x.set_rate_model('Methane', 'ldf', 'constant', k=0.2)
ads_13x.set_rate_model('Helium', 'ldf', 'constant', k=0.5)
ads_13x.heat_of_adsorption['CarbonDioxide'] = 36300.0
ads_13x.heat_of_adsorption['Methane'] = 18800.0
ads_13x.heat_of_adsorption['Helium'] = 0.0

# ---- column ----------------------------------------------------------------------
sim.bed.set_shape('cylinder', diameter=0.025)
sim.bed.ambient_temperature = 298.0
sim.bed.set_thermal_equilibrium('lte')
sim.bed.set_particle_heat_transfer('constant', particle_htc=100.0)
sim.bed.bottom_void.enabled = False
sim.bed.bottom_void.volume = 0.0001
sim.bed.bottom_void.resistance_coefficient = 0.0
