sim.wall.set_material('ss316l', density=8000.0, heat_capacity=500.0, thermal_conductivity=0.0)
sim.wall.thickness = 0.0025
sim.wall.set_boundary('zero_flux')

# ---- layers (feed end first) ------------------------------------------------------
layer_13x = sim.add_layer('13X', composition={'13X': 1.0}, momentum='kozeny_carman', length=1.2, cells=60, bed_void_fraction=0.4516129032258065, particle_diameter=0.0018)
layer_13x.set_dispersion('constant', dispersion_coefficient=0.0)
layer_13x.set_heat_dispersion('constant', heat_dispersion_coefficient=0.0)
layer_13x.set_internal_heat_transfer('dixon')
