sim.initial_conditions.y['Helium'] = 1.0
sim.initial_conditions.y['Methane'] = 0.0
sim.initial_conditions.y['CarbonDioxide'] = 0.0

# ---- cycle -------------------------------------------------------------------------
sim.cycle.number_of_cycles = 1
sim.cycle.step_time_mode = 0
feed = sim.add_step('Feed', time=4100.0)
feed.bottom.set_streams('inlet', [
    sk.Stream('Binary Feed', flow=sk.volumetric_flow(2e-05), y={'Helium': 0.0, 'Methane': 0.5, 'CarbonDioxide': 0.5}, temperature=298.0),
])
feed.top.set_pressure('outlet', 100000.0, y={'CarbonDioxide': 0.0, 'Methane': 0.0, 'Helium': 1.0}, temperature=293.0)

# ---- solver, cyclic steady state, energy balance --------------------------------------
sim.settings.init_step = 1e-10
